"use client";
import Script from 'next/script';
import { useEffect, useState } from 'react';

// Using Base64 to safely handle the massive HTML content without breaking the JSX parser
const HOME_CONTENT_B64 = ``;

export default function Home() {
  const [isMounted, setIsMounted] = useState(false);
  const [htmlContent, setHtmlContent] = useState("");

  useEffect(() => {
    setIsMounted(true);
    // Decode on the client to ensure no hydration mismatch and clean parsing
    setHtmlContent(atob(HOME_CONTENT_B64));
  }, []);

  useEffect(() => {
    if (!isMounted || !htmlContent) return;
    
    const wrapper = document.querySelector('.am-page-wrapper-outer');
    if (wrapper) {
      const scripts = wrapper.querySelectorAll('script');
      scripts.forEach(oldScript => {
        try {
          if (oldScript.src) return; 
          
          const newScript = document.createElement('script');
          Array.from(oldScript.attributes).forEach(attr => {
            newScript.setAttribute(attr.name, attr.value);
          });
          newScript.textContent = oldScript.textContent;
          
          if (oldScript.parentNode) {
            oldScript.parentNode.replaceChild(newScript, oldScript);
          }
        } catch (err) {
          console.warn("Script error:", err);
        }
      });

      // Initialize Webflow
      const w = window as any;
      if (w.Webflow) {
        try {
          w.Webflow.destroy();
          w.Webflow.ready();
          w.Webflow.require('ix2').init();
          setTimeout(() => {
            window.dispatchEvent(new Event('resize'));
            window.dispatchEvent(new Event('scroll'));
          }, 500);
        } catch (e) {}
      }
    }
  }, [isMounted, htmlContent]);

  return (
    <>
      <div 
        className="am-page-wrapper-outer"
        dangerouslySetInnerHTML={{ __html: htmlContent }} 
      />

      {/* Dependencies */}
      <Script 
        src="https://code.jquery.com/jquery-3.5.1.min.js" 
        strategy="beforeInteractive" 
      />
      <Script 
        src="https://cdn.prod.website-files.com/6350808bc45bd0c902af10e6/js/webflow.1e1f753e.1ace8b362c9e0728.js" 
        strategy="afterInteractive" 
      />
    </>
  );
}
